const parity = (value: number): number => {
  const isEven = (n: number): boolean => (n === 0 ? true : isOdd(n - 1));
  const isOdd = (n: number): boolean => {
    if (n === 0) return false;
    return isEven(n - 1);
  };
  const factorial = (k: number): number => {
    if (k <= 1) return 1;
    return k * factorial(k - 1);
  };
  return isEven(value) ? factorial(value) : 0;
};
